CREATE TABLE "challans"."custom_handlers" (
  "id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "name"       text                     NOT NULL,
  "created_by" uuid,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "custom_handlers_name_check" CHECK ((btrim(name) <> ''::text)),
  CONSTRAINT "custom_handlers_pkey" PRIMARY KEY (id)
);

ALTER TABLE "challans"."custom_handlers"
  ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION challans.add_custom_handler (
  p_name text
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  clean_name text := core.clean_text(p_name);
  existing_id uuid;
begin
  perform core.require_module_access('challans');

  if clean_name is null then
    raise exception 'Enter a name.';
  end if;
  if exists (select 1 from core.employees e where lower(e.name) = lower(clean_name)) then
    raise exception '% is an employee: pick them from the list.', clean_name;
  end if;

  select h.id into existing_id
  from challans.custom_handlers h where lower(h.name) = lower(clean_name);
  if existing_id is not null then
    return existing_id;
  end if;

  insert into challans.custom_handlers (name, created_by)
  values (clean_name, auth.uid())
  returning id into existing_id;
  return existing_id;
end;
$function$;

CREATE OR REPLACE FUNCTION challans.can_manage_handlers()
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select core.is_superadmin();
$function$;

CREATE OR REPLACE FUNCTION challans.create_challan (
  p_direction              text,
  p_challan_date           date,
  p_address_id             uuid,
  p_handled_by_name        text,
  p_vehicle_number         text,
  p_declared_value         integer,
  p_notes                  text,
  p_items                  jsonb,
  p_handled_by_employee_id uuid    DEFAULT NULL::uuid
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  clean_handled_by text;
  handler_employee_id uuid;
  series_year smallint := challans.financial_year_of(p_challan_date);
  latest_date date;
  next_number int;
  version_id uuid;
  new_id uuid;
begin
  perform core.require_module_access('challans');

  if p_direction not in ('outward', 'inward') then
    raise exception 'Unknown challan direction "%".', p_direction;
  end if;
  if p_challan_date is null then
    raise exception 'Pick the challan date.';
  end if;
  if p_challan_date > challans.today() then
    raise exception 'The challan date can''t be in the future.';
  end if;
  select r.handler_name, r.handler_employee_id
  into clean_handled_by, handler_employee_id
  from challans.resolve_handler(p_handled_by_name, p_handled_by_employee_id) r;
  if clean_handled_by is null then
    if p_direction = 'outward' then
      raise exception 'Enter who is delivering it.';
    else
      raise exception 'Enter who received it.';
    end if;
  end if;
  if p_declared_value is not null and p_declared_value < 1 then
    raise exception 'The declared value must be more than zero, or left empty.';
  end if;

  next_number := challans.lock_number_series(p_direction, series_year);

  if p_direction = 'outward' then
    select max(challan_date) into latest_date
    from challans.challans
    where direction = 'outward' and financial_year = series_year;

    if p_challan_date < latest_date then
      raise exception 'The last outward challan of % is dated %, so this one can''t be dated earlier.',
        challans.financial_year_label(series_year), to_char(latest_date, 'FMDD Mon YYYY');
    end if;
  end if;

  version_id := challans.lock_latest_version(p_address_id);

  insert into challans.challans (
    direction, challan_date, number, client_address_version_id,
    handled_by_name, handled_by_employee_id, vehicle_number, declared_value,
    notes, created_by
  )
  values (
    p_direction, p_challan_date, next_number, version_id,
    clean_handled_by, handler_employee_id,
    upper(core.clean_text(p_vehicle_number)), p_declared_value,
    core.clean_text(p_notes), auth.uid()
  )
  returning id into new_id;

  perform challans.replace_items(new_id, p_items);

  insert into challans.challan_events (challan_id, event_type, created_by)
  values (new_id, 'created', auth.uid());

  return new_id;
end;
$function$;

CREATE OR REPLACE FUNCTION challans.delete_custom_handler (
  p_id uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not challans.can_manage_handlers() then
    raise exception 'Not allowed' using errcode = '42501';
  end if;

  delete from challans.custom_handlers where id = p_id;
end;
$function$;

CREATE OR REPLACE FUNCTION challans.handler_options()
  RETURNS TABLE (
    kind text,
    id   uuid,
    name text
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  perform core.require_module_access('challans');

  return query
  select options.kind, options.id, options.name
  from (
    select 'employee' as kind, e.id, e.name, 0 as sort_group
    from core.employees e
    where core.employee_status_as_of(e.id, challans.today()) = 'active'
    union all
    select 'custom', h.id, h.name, 1
    from challans.custom_handlers h
  ) options
  order by options.sort_group, lower(options.name);
end;
$function$;

CREATE OR REPLACE FUNCTION challans.rename_custom_handler (
  p_id   uuid,
  p_name text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  clean_name text := core.clean_text(p_name);
begin
  if not challans.can_manage_handlers() then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if clean_name is null then
    raise exception 'Enter a name.';
  end if;
  if exists (select 1 from core.employees e where lower(e.name) = lower(clean_name)) then
    raise exception '% is an employee.', clean_name;
  end if;
  if exists (select 1 from challans.custom_handlers h
             where lower(h.name) = lower(clean_name) and h.id <> p_id) then
    raise exception '% is already in the list.', clean_name;
  end if;

  update challans.custom_handlers set name = clean_name where id = p_id;
  if not found then
    raise exception 'That handler no longer exists.';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION challans.resolve_handler (
  p_name        text,
  p_employee_id uuid
)
  RETURNS TABLE (
    handler_name        text,
    handler_employee_id uuid
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  employee_name text;
  typed_name text := core.clean_text(p_name);
begin
  if p_employee_id is null then
    return query select typed_name, challans.employee_named(typed_name);
    return;
  end if;

  select e.name into employee_name from core.employees e where e.id = p_employee_id;
  if employee_name is null then
    raise exception 'That employee no longer exists.';
  end if;
  return query select employee_name, p_employee_id;
end;
$function$;

CREATE OR REPLACE FUNCTION challans.update_challan (
  p_challan_id             uuid,
  p_address_id             uuid,
  p_use_latest_address     boolean,
  p_handled_by_name        text,
  p_vehicle_number         text,
  p_declared_value         integer,
  p_notes                  text,
  p_items                  jsonb,
  p_handled_by_employee_id uuid    DEFAULT NULL::uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  existing challans.challans;
  old_address_id uuid;
  new_version_id uuid;
  clean_handled_by text;
  handler_employee_id uuid;
  clean_vehicle text := upper(core.clean_text(p_vehicle_number));
  clean_notes text := core.clean_text(p_notes);
  old_items jsonb;
  new_items jsonb;
  changes jsonb := '{}';
begin
  perform core.require_module_access('challans');
  existing := challans.challan_for_update(p_challan_id);

  -- The same employee as before keeps the name the challan was made with,
  -- even if they've since been renamed.
  if p_handled_by_employee_id is not null
     and p_handled_by_employee_id is not distinct from existing.handled_by_employee_id then
    clean_handled_by := existing.handled_by_name;
    handler_employee_id := existing.handled_by_employee_id;
  else
    select r.handler_name, r.handler_employee_id
    into clean_handled_by, handler_employee_id
    from challans.resolve_handler(p_handled_by_name, p_handled_by_employee_id) r;
  end if;
  if clean_handled_by is null then
    if existing.direction = 'outward' then
      raise exception 'Enter who is delivering it.';
    else
      raise exception 'Enter who received it.';
    end if;
  end if;
  if p_declared_value is not null and p_declared_value < 1 then
    raise exception 'The declared value must be more than zero, or left empty.';
  end if;

  select address_id into old_address_id
  from core.client_address_versions where id = existing.client_address_version_id;

  if p_address_id is distinct from old_address_id or p_use_latest_address then
    new_version_id := challans.lock_latest_version(p_address_id);
  else
    new_version_id := existing.client_address_version_id;
  end if;

  if new_version_id <> existing.client_address_version_id then
    changes := changes || jsonb_build_object('address', jsonb_build_object(
      'from', (select v.name_on_challan || ', ' || a.label || ' (v' || v.version || ')'
               from core.client_address_versions v
               join core.client_addresses a on a.id = v.address_id
               where v.id = existing.client_address_version_id),
      'to', (select v.name_on_challan || ', ' || a.label || ' (v' || v.version || ')'
             from core.client_address_versions v
             join core.client_addresses a on a.id = v.address_id
             where v.id = new_version_id)
    ));
  end if;
  if clean_handled_by is distinct from existing.handled_by_name then
    changes := changes || jsonb_build_object('handled_by_name',
      jsonb_build_object('from', existing.handled_by_name, 'to', clean_handled_by));
  end if;
  if clean_vehicle is distinct from existing.vehicle_number then
    changes := changes || jsonb_build_object('vehicle_number',
      jsonb_build_object('from', existing.vehicle_number, 'to', clean_vehicle));
  end if;
  if p_declared_value is distinct from existing.declared_value then
    changes := changes || jsonb_build_object('declared_value',
      jsonb_build_object('from', existing.declared_value, 'to', p_declared_value));
  end if;
  if clean_notes is distinct from existing.notes then
    changes := changes || jsonb_build_object('notes',
      jsonb_build_object('from', existing.notes, 'to', clean_notes));
  end if;

  old_items := challans.items_json(p_challan_id);
  perform challans.replace_items(p_challan_id, p_items);
  new_items := challans.items_json(p_challan_id);
  if new_items <> old_items then
    changes := changes || jsonb_build_object('items',
      jsonb_build_object('from', old_items, 'to', new_items));
  end if;

  -- Saved without changing anything: no history row.
  if changes = '{}'::jsonb then
    return;
  end if;

  update challans.challans
  set client_address_version_id = new_version_id,
      handled_by_name = clean_handled_by,
      handled_by_employee_id = handler_employee_id,
      vehicle_number = clean_vehicle,
      declared_value = p_declared_value,
      notes = clean_notes,
      updated_at = now()
  where id = p_challan_id;

  insert into challans.challan_events (challan_id, event_type, changes, created_by)
  values (p_challan_id, 'edited', changes, auth.uid());
end;
$function$;

ALTER TABLE "challans"."custom_handlers"
