CREATE VIEW "challans"."handler_choices" WITH (security_invoker=true) AS  SELECT kind,
    id,
    name
   FROM challans.handler_options() handler_options(kind, id, name);

CREATE UNIQUE INDEX custom_handlers_name_key ON challans.custom_handlers USING btree (lower(name));

CREATE POLICY "custom_handlers_select" ON "challans"."custom_handlers"
  FOR SELECT
  TO PUBLIC
  USING (core.has_module_access('challans'::text));

